-- Reference data: the Anime and Video Games universes (generated, original texts).
-- Idempotent: rows that already exist are kept. Independent, unofficial fan community:
-- franchise and character names are used descriptively only.

INSERT INTO public.universes (slug, name, tagline, description, status, sort_order) VALUES
  ('animes', '{"pt-BR": "Animes", "en": "Anime"}', '{"pt-BR": "Do shōnen ao isekai: as maiores aventuras dos animes e mangás.", "en": "From shōnen to isekai: the greatest anime and manga adventures."}', '{"pt-BR": "Descubra seu estilo de anime, explore o guia de séries e filmes, o arquivo de personagens e a biblioteca de mangás, debata teorias, mostre suas fan arts e jogue quizzes e desafios. Comunidade de fãs independente e não oficial.", "en": "Find your anime style, explore the series and film guide, the character archive and the manga library, debate theories, share fan art and play quizzes and challenges. Independent, unofficial fan community."}', 'active', 90),
  ('games', '{"pt-BR": "Games", "en": "Video Games"}', '{"pt-BR": "Consoles, PCs e celulares: o universo de quem vive de jogar.", "en": "Consoles, PCs and phones: the universe of everyone who loves to play."}', '{"pt-BR": "Escolha sua classe de jogador, explore o guia de clássicos, o arquivo de personagens e a biblioteca de livros dos games, debata teorias e lançamentos e jogue quizzes e desafios com outros gamers. Comunidade de fãs independente e não oficial.", "en": "Pick your player class, explore the classics guide, the character archive and the gaming book library, debate theories and releases and play quizzes and challenges with other gamers. Independent, unofficial fan community."}', 'active', 100)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.universe_settings (universe_id, theme, features, identity_config)
SELECT id, '{"primary": "#e63962", "secondary": "#2b1d3a", "accent": "#ffd166", "background": "#0b0710", "glow": "#ff8fab"}'::jsonb, '["anime_style", "anime_guide", "character_archive", "books", "quizzes", "rankings", "theories", "discussions", "fan_art", "events", "challenges", "vip_lounge"]'::jsonb, '{"type": "anime_style", "label": {"pt-BR": "Seu estilo de anime", "en": "Your anime style"}, "options": [{"key": "shonen", "name": {"pt-BR": "Shōnen", "en": "Shōnen"}, "color": "#ff6b35", "traits": {"pt-BR": ["ação", "amizade"], "en": ["action", "friendship"]}}, {"key": "shojo", "name": {"pt-BR": "Shōjo", "en": "Shōjo"}, "color": "#ff8fab", "traits": {"pt-BR": ["romance", "emoção"], "en": ["romance", "emotion"]}}, {"key": "seinen", "name": {"pt-BR": "Seinen", "en": "Seinen"}, "color": "#6c757d", "traits": {"pt-BR": ["histórias maduras", "reflexão"], "en": ["mature stories", "reflection"]}}, {"key": "isekai", "name": {"pt-BR": "Isekai", "en": "Isekai"}, "color": "#7b2cbf", "traits": {"pt-BR": ["outros mundos", "imaginação"], "en": ["other worlds", "imagination"]}}, {"key": "slice_of_life", "name": {"pt-BR": "Slice of life", "en": "Slice of life"}, "color": "#80b918", "traits": {"pt-BR": ["cotidiano", "calma"], "en": ["everyday life", "calm"]}}, {"key": "mecha", "name": {"pt-BR": "Mecha", "en": "Mecha"}, "color": "#4895ef", "traits": {"pt-BR": ["tecnologia", "estratégia"], "en": ["technology", "strategy"]}}]}'::jsonb FROM public.universes WHERE slug = 'animes'
ON CONFLICT (universe_id) DO NOTHING;
INSERT INTO public.universe_settings (universe_id, theme, features, identity_config)
SELECT id, '{"primary": "#3a86ff", "secondary": "#14213d", "accent": "#00f5d4", "background": "#03060d", "glow": "#4cc9f0"}'::jsonb, '["gamer_class", "games_guide", "character_archive", "books", "quizzes", "rankings", "theories", "discussions", "fan_art", "events", "challenges", "vip_lounge"]'::jsonb, '{"type": "gamer_class", "label": {"pt-BR": "Sua classe de jogador", "en": "Your player class"}, "options": [{"key": "strategist", "name": {"pt-BR": "Estrategista", "en": "Strategist"}, "color": "#4361ee", "traits": {"pt-BR": ["planejamento", "paciência"], "en": ["planning", "patience"]}}, {"key": "explorer", "name": {"pt-BR": "Explorador(a)", "en": "Explorer"}, "color": "#2a9d8f", "traits": {"pt-BR": ["curiosidade", "mundos abertos"], "en": ["curiosity", "open worlds"]}}, {"key": "competitor", "name": {"pt-BR": "Competitivo(a)", "en": "Competitor"}, "color": "#e63946", "traits": {"pt-BR": ["reflexos", "ranking"], "en": ["reflexes", "ranked play"]}}, {"key": "collector", "name": {"pt-BR": "Caçador(a) de troféus", "en": "Trophy hunter"}, "color": "#f4a261", "traits": {"pt-BR": ["100%", "dedicação"], "en": ["100%", "dedication"]}}, {"key": "storyteller", "name": {"pt-BR": "Amante de histórias", "en": "Story lover"}, "color": "#9d4edd", "traits": {"pt-BR": ["narrativa", "personagens"], "en": ["narrative", "characters"]}}, {"key": "speedrunner", "name": {"pt-BR": "Speedrunner", "en": "Speedrunner"}, "color": "#00f5d4", "traits": {"pt-BR": ["rotas", "precisão"], "en": ["routes", "precision"]}}]}'::jsonb FROM public.universes WHERE slug = 'games'
ON CONFLICT (universe_id) DO NOTHING;

INSERT INTO public.lore_entries (universe_id, section, slug, title, subtitle, summary, sort_order) SELECT id, 'anime_guide', 'one-piece', '{"pt-BR": "One Piece", "en": "One Piece"}', '{"pt-BR": "Anime · 1999–", "en": "Anime · 1999–"}', '{"pt-BR": "Luffy e seus companheiros cruzam os mares em busca do maior tesouro do mundo. Uma jornada sobre liberdade e amizade.", "en": "Luffy and his crew sail the seas in search of the world''s greatest treasure. A journey about freedom and friendship."}', 10 FROM public.universes WHERE slug = 'animes' ON CONFLICT (universe_id, section, slug) DO NOTHING;
INSERT INTO public.lore_entries (universe_id, section, slug, title, subtitle, summary, sort_order) SELECT id, 'anime_guide', 'naruto', '{"pt-BR": "Naruto", "en": "Naruto"}', '{"pt-BR": "Anime · 2002–2017", "en": "Anime · 2002–2017"}', '{"pt-BR": "Um jovem ninja rejeitado pela vila treina para ser reconhecido por todos e se tornar o líder de Konoha.", "en": "A young ninja shunned by his village trains to earn everyone''s respect and lead Konoha."}', 20 FROM public.universes WHERE slug = 'animes' ON CONFLICT (universe_id, section, slug) DO NOTHING;
