INSERT INTO public.lore_entries (universe_id, section, slug, title, subtitle, summary, sort_order) SELECT id, 'anime_guide', 'cavaleiros-do-zodiaco', '{"pt-BR": "Os Cavaleiros do Zodíaco", "en": "Saint Seiya"}', '{"pt-BR": "Anime · 1986–1989", "en": "Anime · 1986–1989"}', '{"pt-BR": "Jovens guerreiros protegidos por constelações defendem a deusa Atena. Um fenômeno no Brasil dos anos 90.", "en": "Young warriors guarded by constellations defend the goddess Athena. A phenomenon in 1990s Brazil."}', 40 FROM public.universes WHERE slug = 'animes' ON CONFLICT (universe_id, section, slug) DO NOTHING;
