-- Quiz nights use the universe's normal trivia quiz.
UPDATE public.events e SET quiz_id = q.id FROM public.quizzes q, public.universes u
 WHERE u.id = e.universe_id AND q.universe_id = u.id AND u.slug IN ('animes', 'games')
   AND e.slug = 'noite-de-quiz' AND q.slug IN ('arco-intermediario', 'fase-intermediaria') AND e.quiz_id IS NULL;
